<template>
  <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-4">
    <ApplicationsDetailsDataItem
      v-for="item in applicationsDetailsDataItems"
      :key="item.label"
      :label="item.label"
      :icon="item.icon"
      :value="item.value"
    />
    <ApplicationsDetailsDataItem
      v-if="isCanvasserDetails(projectDetails)"
      label="Status"
      :is-no-content="Boolean(projectDetails.application_status)"
    >
      <template v-if="projectDetails.application_status" #header-right>
        <Badge :variant="getApplicationStatus(projectDetails.application_status).variant">{{
          getApplicationStatus(projectDetails.application_status).label
        }}</Badge>
      </template>
      <span class="text-accent-foreground">In Progress</span>
      <template v-if="!projectDetails.application_status" #content>
        <Button class="w-full" variant="default" :loading="isApplyingToProject" @click="applyClick">
          Submit Application
        </Button>
      </template>
    </ApplicationsDetailsDataItem>
    <ApplicationsDetailsDataItem
      v-else-if="isManagerOrAdminDetails(projectDetails)"
      label="Approved Canvassers"
      :icon="Users"
      :value="`${projectDetails.approved_canvassers}/${projectDetails.staffing_goal}`"
    >
      <template #content>
        <Progress v-model="progress" />
      </template>
    </ApplicationsDetailsDataItem>
  </div>
</template>

<script setup lang="ts">
import type {
  UpcomingProjectDetailsForCanvasser,
  UpcomingProjectDetailsForManager,
  UpcomingProjectDetailsForAdmin,
  UpcomingProjectDetailsPublic,
} from '~/client';
import { Users, Calendar, CircleCheck, CircleDollarSign, BriefcaseBusiness } from 'lucide-vue-next';
import { useApplyToProject } from '~/mutations/applications';
import { getApplicationStatus } from '~/constants/applications';
import { getProjectTypeLabel } from '~/constants/projects';

interface Props {
  projectDetails:
    | UpcomingProjectDetailsForCanvasser
    | UpcomingProjectDetailsForManager
    | UpcomingProjectDetailsForAdmin
    | UpcomingProjectDetailsPublic;
}

const props = defineProps<Props>();

function isCanvasserDetails(
  projectDetails:
    | UpcomingProjectDetailsForCanvasser
    | UpcomingProjectDetailsForManager
    | UpcomingProjectDetailsForAdmin
    | UpcomingProjectDetailsPublic
): projectDetails is UpcomingProjectDetailsForCanvasser {
  return 'status' in projectDetails;
}

function isManagerOrAdminDetails(
  projectDetails:
    | UpcomingProjectDetailsForCanvasser
    | UpcomingProjectDetailsForManager
    | UpcomingProjectDetailsForAdmin
    | UpcomingProjectDetailsPublic
): projectDetails is UpcomingProjectDetailsForManager | UpcomingProjectDetailsForAdmin {
  return 'approved_canvassers' in projectDetails;
}

const progress = computed(() => {
  if (isManagerOrAdminDetails(props.projectDetails)) {
    return getProgressValue(props.projectDetails.approved_canvassers, props.projectDetails.staffing_goal);
  }
  return 0;
});

//TODO merge this with same array in [hash].vue file
const applicationsDetailsDataItems = computed(() => {
  const items = [
    {
      label: 'Type',
      value: getProjectTypeLabel(props.projectDetails.type),
      icon: BriefcaseBusiness,
    },
    {
      label: 'Duration',
      value: `${startEndDate(props.projectDetails.start_date, props.projectDetails.end_date)}`,
      icon: Calendar,
    },
    {
      label: `Payment per ${isUpcomingSignatureProjectPricing(props.projectDetails.pricing) ? 'Signature' : 'Hour'}`,
      value: upcomingProjectPricing(props.projectDetails.pricing),
      icon: CircleDollarSign,
    },
  ];

  if (!isCanvasserDetails(props.projectDetails)) {
    items.splice(2, 0, {
      label: 'Goal',
      value: `${goal(props.projectDetails.goal)}`,
      icon: CircleCheck,
    });
  }

  return items;
});

const { userData } = useUserRole();

const { userApplyToProject, isApplyingToProject } = useApplyToProject();

function applyClick() {
  if (!userData.value?.id) return;

  const data = {
    project_id: props.projectDetails.id,
    user_id: userData.value?.id,
  };
  userApplyToProject(data);
}
</script>

<style scoped lang="scss"></style>
