import { applyToProject } from '~/client';
import type { UserApplicationRequest, UpcomingProjectDetailsForCanvasser, ProjectApplicationStatus } from '~/client';

export const useApplyToProject = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: userApplyToProject, asyncStatus } = useMutation({
    mutation: (applyData: UserApplicationRequest) =>
      applyToProject({
        composable: '$fetch',
        body: {
          ...applyData,
        },
      }),
    onSuccess: async (_, { project_id }) => {
      queryCache.setQueryData(
        ['applications.details', project_id],
        (oldData: UpcomingProjectDetailsForCanvasser | undefined) => {
          if (!oldData) return oldData;
          return {
            ...oldData,
            application_status: 'applied' as ProjectApplicationStatus,
          };
        }
      );
    },
    onError: (error) => {
      console.error('Error canvaser apply to project:', error);
      showToastError(error);
    },
  });

  return {
    userApplyToProject,
    isApplyingToProject: computed(() => asyncStatus.value === 'loading'),
  };
});
