<template>
  <AppLoader v-if="isLoading" subject="application details" @vue:before-unmount="setProjectType" />
  <AppError v-else-if="error" title="Failed to load application details" :error="error" />
  <AppEmpty v-else-if="!projectDetails" subject="application details" />
  <section v-else class="flex flex-col gap-10">
    <PageTitle :title="projectDetails.name" show-doc />
    <section class="flex flex-col gap-4">
      <GoBackButton
        v-if="isAdminOrManager || (isCanvasser && isUpcomingProjectInitially)"
        subject="applications"
        :fallback-to="{ name: 'applications-upcoming' }"
      />
      <GoBackButton
        v-else-if="isCanvasser && !isUpcomingProjectInitially"
        subject="applications"
        :fallback-to="{ name: 'applications-my' }"
      />
      <section class="grid grid-cols-3 gap-4">
        <ApplicationsDetailsDescription class="col-span-3 lg:col-span-2" :description="projectDetails.description" />
        <ApplicationsDetailsData class="col-span-3 lg:col-span-1" :project-details="projectDetails" />
      </section>
      <section class="flex flex-col gap-3">
        <ApplicationsDetailsTable
          v-if="isAdminOrManager && isUpcomingProjectPricingForManagerOrAdmin(projectDetails.pricing)"
          :payment="projectDetails.pricing"
          :project-id="projectDetails.id"
          :project-name="projectDetails.name"
          :project-type="projectDetails.type"
          :payment-enabled="projectDetails.pricing.payments_enabled"
        />
      </section>
    </section>
  </section>
</template>

<script setup lang="ts">
definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'application',
});

const { isLoading, error, projectDetails } = useApplicationDetails();

const { isAdminOrManager, isCanvasser } = useUserRole();

const isUpcomingProjectInitially = ref<boolean>(false);

function setProjectType() {
  if (isCanvasser.value && !error.value && projectDetails.value && 'status' in projectDetails.value)
    isUpcomingProjectInitially.value = projectDetails.value.status === 'active';
}

onUnmounted(() => (isUpcomingProjectInitially.value = false));
</script>

<style scoped lang="scss"></style>
